/** Pages are 1-based. Returns { items, page, totalPages }; an empty list has one empty page. */
export function paginate(items, page, size) {
  if (!Array.isArray(items)) throw new TypeError("items must be an array");
  if (!Number.isSafeInteger(page) || page < 1 || !Number.isSafeInteger(size) || size < 1) throw new RangeError("page and size must be positive integers");
  const totalPages = Math.max(1, Math.floor(items.length / size));
  const start = page * size;
  return { items: items.slice(start, start + size), page, totalPages };
}
